    console.log(`  drafts written:     ${report.draftsWritten.length}`);
    for (const d of report.draftsWritten) console.log(`    - ${d}`);
    console.log(`  feedback drafts:     ${report.feedbackDrafts.length}`);
    if (cfg.liveSubmit) {
      console.log("  NOTE: liveSubmit enabled but this build does NOT post; use draft manifests with submitDraft().");
    }
  } else if (cmd === "plan") {
    const report = await planPipeline(cfg);
    console.log(`plan (mode=${report.mode}, ${report.runTs})`);
    console.log(`markets seen: ${report.marketsSeen}, eligible: ${report.marketsEligible}`);
    const ranked = report.marketsConsidered;
    for (const m of ranked) {
      const spec = (await import("./miners/specs.js")).SPECS_BY_MARKET.has(m.address);
      console.log(
        `  eligible  cutoff=${m.evidenceCutoffAt} p(yes)=${m.odds.yes.toFixed(3)} spec=${spec ? "yes" : "no"} ${m.question.slice(0, 60)}`,
      );
    }
    for (const s of report.marketSkips) {
      console.log(`  skip      cutoff=${m0(s.address)} ${s.question.slice(0, 50)} :: ${s.reason}`);
    }
  } else {
    console.error("usage: cli.ts run|plan [--mode=mock|live] [--live-submit] [--max-drafts=N]");
    process.exit(2);
  }
}

